<?php
require_role('officer');$counts=officer_counts();$uid=user()['id'];
$coverage=array_column(q('SELECT a.name FROM officer_areas oa JOIN service_areas a ON a.id=oa.area_id WHERE oa.officer_id=? ORDER BY a.name',[$uid])->fetchAll(),'name');
$review=q(issue_query()." WHERE i.officer_id=? AND i.status IN ('Assigned','In Progress') AND i.maintenance_stage='Review' ORDER BY i.updated_at,i.id LIMIT 5",[$uid])->fetchAll();
$urgent=q(issue_query()." WHERE i.officer_id=? AND i.status IN ('Assigned','In Progress') AND COALESCE(i.maintenance_stage,'')<>'Review' AND (i.priority='High' OR ".staff_overdue_sql().") ORDER BY ".staff_overdue_sql()." DESC,FIELD(i.priority,'High','Medium','Low'),i.created_at LIMIT 5",[$uid])->fetchAll();
layout_start('My work overview','Your supervision summary · Assign teams, review evidence and keep work moving.');
?><div class="officer-workspace"><section class="officer-overview-cards" aria-label="My work summary"><?php foreach([
 ['Needs team',$counts['needs_team'],'Choose a maintenance team','assigned&tab=needs_team','⇢'],
 ['Team working',$counts['team_working'],'Monitor active team work','assigned&tab=team_working','↻'],
 ['Needs my review',$counts['review'],'Inspect team completion','assigned&tab=review','✓'],
 ['Awaiting admin',$counts['admin'],'Waiting for final approval','assigned&tab=admin','◷'],
 ['Overdue',$counts['overdue'],'Review delayed assignments','assigned&late=1','!']
] as $card):?><a class="stat" href="<?=e('index.php?page='.$card[3])?>"><div class="row between"><span><?=$card[0]?></span><b class="stat-icon"><?=$card[4]?></b></div><strong><?=$card[1]?></strong><small><?=$card[2]?> ↗</small></a><?php endforeach;?></section>
<?php if($counts['confirmation']):?><div class="officer-notice"><strong><?=$counts['confirmation']?> older assignment(s) need admin confirmation.</strong> Submitted/Verified reports with an officer are counted in open work, but team work cannot start until an admin confirms them. <a href="index.php?page=assigned&amp;tab=confirmation">View reports →</a></div><?php endif;?>
<section class="panel"><div class="row between"><div><h2>Your next step is in Assigned to me.</h2><p class="small muted"><?=$counts['open']?> open assignments · Service coverage: <?=e($coverage?implode(', ',$coverage):'Unrestricted')?>.</p></div><a class="button" href="index.php?page=assigned">Open my assignments →</a></div></section>
<div class="two-col section-space"><section class="panel officer-brief"><div class="row between"><h3>Team completions to review</h3><a class="text-link" href="index.php?page=assigned&amp;tab=review">View all ↗</a></div><p class="small muted">Up to 5 submissions, oldest first. Review before forwarding to the administrator.</p><?php if(!$review):?><p class="small muted">No team completions need your review.</p><?php endif;?><?php foreach($review as $i):?><article class="summary-line"><a class="table-title" href="index.php?page=issue&amp;id=<?=$i['id']?>#maintenance-work">#<?=$i['id']?> · <?=e($i['title'])?></a><p class="small muted"><?=e($i['maintenance_team'])?> · <?=e($i['area_name']?:'Area not specified')?></p><a class="button secondary officer-row-action" href="index.php?page=issue&amp;id=<?=$i['id']?>#maintenance-work">Review completion →</a></article><?php endforeach;?></section>
<section class="panel officer-brief"><div class="row between"><h3>Needs your attention</h3><a class="text-link" href="index.php?page=assigned&amp;late=1">Overdue work ↗</a></div><p class="small muted">Up to 5 high-priority or overdue assignments. Completion reviews are listed separately.</p><?php if(!$urgent):?><p class="small muted">No urgent work currently needs attention.</p><?php endif;?><?php foreach($urgent as $i):$next=officer_next($i);?><article class="summary-line"><div class="row between"><a class="table-title" href="<?=e($next[1])?>">#<?=$i['id']?> · <?=e($i['title'])?></a><span class="priority-chip p-<?=strtolower($i['priority'])?>"><?=e($i['priority'])?></span></div><p class="small muted"><?=e($next[2])?> · <?=e($i['area_name']?:'Area not specified')?></p><a class="text-link" href="<?=e($next[1])?>"><?=e($next[0])?> →</a></article><?php endforeach;?></section></div>
<section class="panel section-space"><div class="row between"><div><h3>Waiting for admin review</h3><p class="small muted"><?=$counts['admin']?> submission(s) awaiting final approval. Historical filters and CSV downloads are in Reports & export.</p></div><a class="button secondary" href="index.php?page=reports">Reports & export →</a></div></section></div><?php layout_end();
